insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0691',691,19,'Touring','Du lịch','','Check-in desk','Quầy làm thủ tục','/ˈtʃɛk ɪn ˈdɛsk/','The guide explained what to expect from check-in desk during the trip.','Hướng dẫn viên giải thích những điều có thể mong đợi từ quầy làm thủ tục trong chuyến đi.','','Nghe thông tin đặt chỗ, giờ tập trung, giá và điểm đến.','Bổ sung','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0692',692,20,'Adjectives','Tính từ','','Energetic','Tràn đầy năng lượng','/ˌɛnɚˈdʒɛtɪk/','The guide described the site as energetic during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là tràn đầy năng lượng trong buổi giới thiệu cho khách tham quan.','lively','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0693',693,20,'Adjectives','Tính từ','','Social','Thuộc xã hội','/ˈsoʊʃəl/','The university offers several social activities for first-year students.','Trường đại học tổ chức một số hoạt động xã hội cho sinh viên năm nhất.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0694',694,20,'Adjectives','Tính từ','','Ancient','Cổ đại','/ˈeɪntʃənt/','The guide described the site as ancient during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là cổ đại trong buổi giới thiệu cho khách tham quan.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0695',695,20,'Adjectives','Tính từ','','Necessary','Cần thiết','/ˈnɛsəˌsɛɹi/','A written permit is necessary before entering the site.','Cần có giấy phép bằng văn bản trước khi vào khu vực này.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0696',696,20,'Adjectives','Tính từ','','Fantastic','Tuyệt vời','/fænˈtæstɪk/','The guide described the site as fantastic during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là tuyệt vời trong buổi giới thiệu cho khách tham quan.','excellent','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0697',697,20,'Adjectives','Tính từ','','Exciting','Thú vị','/ɪkˈsaɪtɪŋ/','The guide described the site as exciting during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là thú vị trong buổi giới thiệu cho khách tham quan.','thrilling','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0698',698,20,'Adjectives','Tính từ','','Fabulous','Tuyệt diệu','/ˈfæbjələs/','The guide described the site as fabulous during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là tuyệt diệu trong buổi giới thiệu cho khách tham quan.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0699',699,20,'Adjectives','Tính từ','','Dull','Buồn tẻ','/ˈdʌl/','The guide described the site as dull during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là buồn tẻ trong buổi giới thiệu cho khách tham quan.','boring','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0700',700,20,'Adjectives','Tính từ','','Comfortable','Thoải mái','/ˈkʌmfɚtəbəl/','The seating area is comfortable enough for a two-hour lecture.','Khu vực chỗ ngồi đủ thoải mái cho bài giảng hai giờ.','cosy','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0701',701,20,'Adjectives','Tính từ','','Convenient','Tiện lợi','/kənˈvinjənt/','The new bus timetable is more convenient for commuters.','Lịch xe buýt mới thuận tiện hơn cho người đi làm.','handy','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0702',702,20,'Adjectives','Tính từ','','Suitable','Phù hợp','/ˈsutəbəl/','The tutor recommended a suitable textbook for beginners.','Giảng viên hướng dẫn đề xuất một cuốn giáo trình phù hợp cho người mới bắt đầu.','appropriate','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0703',703,20,'Adjectives','Tính từ','','Affordable','Giá phải chăng','/əˈfɔɹdəbəl/','The hostel provides affordable accommodation near the campus.','Nhà trọ cung cấp chỗ ở giá phải chăng gần khuôn viên trường.','inexpensive','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0704',704,20,'Adjectives','Tính từ','','Voluntary','Tự nguyện','/ˈvɑləntɛɹi/','Participation in the follow-up interview is voluntary.','Việc tham gia phỏng vấn bổ sung là tự nguyện.','optional','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0705',705,20,'Adjectives','Tính từ','','Mandatory','Bắt buộc','/ˈmændəˌtɔɹi/','Attendance at the first laboratory session is mandatory.','Việc tham dự buổi thực hành đầu tiên là bắt buộc.','required','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0706',706,20,'Adjectives','Tính từ','','Compulsory','Bắt buộc','/kəmˈpʌlsɚi/','Safety training is compulsory for every new employee.','Đào tạo an toàn là bắt buộc đối với mọi nhân viên mới.','obligatory','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0707',707,20,'Adjectives','Tính từ','','Temporary','Tạm thời','/ˈtɛmpɚˌɛɹi/','A temporary entrance will be used during the renovation.','Một lối vào tạm thời sẽ được sử dụng trong thời gian cải tạo.','short-term','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0708',708,20,'Adjectives','Tính từ','','Permanent','Vĩnh viễn','/ˈpɝmənənt/','The exhibition will become a permanent feature of the museum.','Triển lãm sẽ trở thành hạng mục thường trực của bảo tàng.','long-lasting','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0709',709,20,'Adjectives','Tính từ','','Immense','Bao la','/ˌɪˈmɛns/','The guide described the site as immense during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là rộng lớn trong buổi giới thiệu cho khách tham quan.','enormous','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0710',710,20,'Adjectives','Tính từ','','Vast','Rộng lớn','/ˈvæst/','The guide described the site as vast during the visitor briefing.','Hướng dẫn viên mô tả địa điểm này là bao la trong buổi giới thiệu cho khách tham quan.','extensive','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0711',711,20,'Adjectives','Tính từ','','Salty','Mặn','/ˈsɔlti/','The guide warned visitors that the lake water was extremely salty.','Hướng dẫn viên cảnh báo du khách rằng nước hồ rất mặn.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0712',712,20,'Adjectives','Tính từ','','Extinct','Tuyệt chủng','/ɪksˈtɪŋkt/','The museum displayed fossils from an extinct species of bird.','Bảo tàng trưng bày hóa thạch của một loài chim đã tuyệt chủng.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0713',713,20,'Adjectives','Tính từ','','Vulnerable','Dễ bị tổn thương','/ˈvʌlnɚəbəl/','The project supports vulnerable residents during extreme weather.','Dự án hỗ trợ những cư dân dễ bị tổn thương trong thời tiết khắc nghiệt.','at risk','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0714',714,20,'Adjectives','Tính từ','','Pessimistic','Bi quan','/ˌpɛsəˈmɪstɪk/','The researcher was pessimistic about the project chances of success.','Nhà nghiên cứu bi quan về khả năng thành công của dự án.','negative about the future','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0715',715,20,'Adjectives','Tính từ','','Optimistic','Lạc quan','/ˌɑptəˈmɪstɪk/','The organisers were optimistic that more volunteers would join.','Ban tổ chức lạc quan rằng sẽ có thêm tình nguyện viên tham gia.','hopeful','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
