insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0720',720,20,'Adjectives','Tính từ','','Confident','Tự tin','/ˈkɑnfədənt/','After the workshop, participants felt more confident about public speaking.','Sau hội thảo, người tham gia cảm thấy tự tin hơn khi nói trước đám đông.','self-assured','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
