insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0735',735,20,'Adjectives','Tính từ','','Optional','Không bắt buộc','/ˈɑpʃənəl/','The guided walking tour is optional for all conference guests.','Chuyến đi bộ có hướng dẫn là hoạt động không bắt buộc dành cho khách dự hội nghị.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Bổ sung','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0736',736,20,'Adjectives','Tính từ','','Remote','Xa xôi','/ɹɪˈmoʊt/','The research station is located in a remote mountain valley.','Trạm nghiên cứu nằm trong một thung lũng núi xa xôi.','','Nghe sắc thái tính từ và từ trái nghĩa trong câu chuyển ý.','Bổ sung','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
