insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0738',738,21,'Hobbies','Sở thích','','Caving','Khám phá hang động','/ˈkeɪvɪŋ/','The leisure centre is offering beginner sessions in caving next month.','Trung tâm giải trí sẽ tổ chức các buổi học khám phá hang động dành cho người mới vào tháng tới.','','Nghe tên sở thích và cách diễn đạt tương đương.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
