insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0853',853,24,'Measurement','Đo lường','','Width','Chiều rộng','/ˈwɪdθ/','The laboratory manual explains how to measure width accurately.','Sổ tay phòng thí nghiệm giải thích cách đo chiều rộng chính xác.','breadth','Phân biệt width và length; nghe con số đi kèm.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
