insert into public.listening_vocabulary_entries (id,source_order,topic_id,topic_en,topic_vi,subtopic,word,meaning_vi,ipa_us_approx,example_en,example_vi,listening_paraphrase,listening_note,source_type,level_label,source_archive_sha256) values ('LST-0855',855,24,'Measurement','Đo lường','','Altitude','Độ cao so với mực nước biển','/ˈæltəˌtud/','The technician recorded the altitude before starting the experiment.','Kỹ thuật viên ghi lại độ cao so với mực nước biển trước khi bắt đầu thí nghiệm.','','Nghe đơn vị, số đo, dấu thập phân và phép làm tròn.','Trong ảnh','IELTS Listening','50ae062863032468fd6274a69eadf8cdf1bc77aa379bb905c2a256a847a99d29') on conflict (id) do nothing;
